long factorial(int n) {
    if (n <= 1) return 1; // PRZYPADEK BAZOWY
    return n * factorial(n - 1); // PRZYPADEK REKURENCYJNY - mniejszy podproblem
}

// naiwna - O(2^n), liczy te same podproblemy wielokrotnie
long fibonacciNaiwny(int n) {
    if (n <= 1) return n;
    return fibonacciNaiwny(n - 1) + fibonacciNaiwny(n - 2);
}

// z memoizacja - O(n), kazdy podproblem liczony TYLKO RAZ
Map<Integer, Long> zapamietane = new HashMap<>();
long fibonacciZapamietany(int n) {
    if (n <= 1) return n;
    if (zapamietane.containsKey(n)) return zapamietane.get(n); // JUZ policzone - odczytaj
    long wynik = fibonacciZapamietany(n - 1) + fibonacciZapamietany(n - 2);
    zapamietane.put(n, wynik); // zapamietaj na przyszlosc
    return wynik;
}

long factorial_BLAD(int n) {
    if (n <= 1) return 1;
    return n * factorial_BLAD(n); // BLAD: brak "- 1" - n nigdy sie nie zmniejsza!
} // StackOverflowError przy kazdym wywolaniu z n > 1

long factorial_OK(int n) {
    if (n <= 1) return 1;
    return n * factorial_OK(n - 1); // POPRAWNIE: n-1 zawsze zblizA sie do przypadku bazowego
}
